 ('law:trib:IBBI_NCLT:ibbi_nclt-73219e6fcd0d8b5c',30,'ae447f924b225bbce5ad7d5bfa5c5fdf0ad602f44ed839055bb6546221b97c56','create-listing',''),
 ('law:trib:IBBI_NCLT:ibbi_nclt-7a8575210da3333c',119,'75d670a32899a333084c9c652596ca9d86a93ace3b5a87ab91c23e84f2468975','create-listing','')
), d as (
 select s.*, doc.id document_id, doc.indexed_at, doc.content_sha256,
  doc.content_sha256 = s.text_sha256 text_hash_matches_decision,
  doc.content_sha256 = encode(sha256(convert_to(doc.ocr_text,'UTF8')),'hex') stored_text_hash_valid,
  (select count(*) from public.document_chunks c where c.document_id=doc.id) actual_chunks,
  (select count(*) from public.document_chunks c where c.document_id=doc.id and c.embedding is null) missing_vectors,
  (select count(*) from public.ingest_jobs j where j.document_id=doc.id) jobs,
  (select max(j.status) from public.ingest_jobs j where j.document_id=doc.id) job_status,
  (select sum(j.embed_tokens) from public.ingest_jobs j where j.document_id=doc.id) embed_tokens,
  (select sum(j.embed_cost_usd) from public.ingest_jobs j where j.document_id=doc.id) embed_cost_usd,
  (select sum(j.ocr_pages) from public.ingest_jobs j where j.document_id=doc.id) ocr_pages,
  p.status publication, l.record_id, r.row_key, r.created_at record_created, r.source_url = doc.file_url listing_url_matches,
  (select count(*) from public.law_source_memberships m where m.source_key=s.source_key) memberships
 from selected s
 left join public.documents doc on doc.source_key=s.source_key
 left join public.law_publications p on p.document_id=doc.id
 left join public.law_document_links l on l.document_id=doc.id
 left join public.law_records r on r.id=l.record_id)
select count(*) selected, count(document_id) registered, count(indexed_at) indexed,
 count(*) filter (where actual_chunks=expected_chunks) chunk_count_match, sum(actual_chunks) chunks, sum(missing_vectors) missing_vectors,
 count(*) filter (where text_hash_matches_decision and stored_text_hash_valid) text_hash_ok,
 count(*) filter (where jobs=1) one_job_each, count(*) filter (where job_status='succeeded') jobs_succeeded,
 sum(embed_tokens) embed_tokens, sum(embed_cost_usd) embed_cost_usd, sum(ocr_pages) ocr_pages,
 count(*) filter (where publication='published') published, count(*) filter (where listing_url_matches) listing_url_ok,
 count(*) filter (where memberships=1) one_membership_each, count(distinct record_id) distinct_records,
 count(*) filter (where proposal='link-existing' and row_key=existing_row_key) linked_existing_as_reviewed,
 count(*) filter (where proposal='create-listing' and row_key like 'law-order:%' and record_created >= '2026-10-26 06:50:00+00') created_as_reviewed,
 (select count(*) from public.law_records where created_at >= '2026-10-26 06:50:00+00') new_law_records
from d;
